<?php declare(strict_types=1);$types=$catalogue['types']??[];$members=$catalogue['members']??[];$people=$catalogue['people']??[];$programmes=$catalogue['programmes']??[];$events=$catalogue['events']??[];$certificates=$catalogue['certificates']??[];?><section class="section"><div class="container-wide"><div class="section-heading"><p class="eyebrow">Authorized administration</p><h1>Certificates</h1><p>Issue, configure and revoke auditable certificate records.</p></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?><?php if($token=$sessionToken??null):?><div class="notice" role="status">One-time verification token: <?= $e($token) ?></div><?php endif;?>
<details class="admin-panel"><summary>Create certificate type</summary><form method="post" action="/admin/certificate-types" class="form-grid"><?= $csrf->field() ?><label>Code<input name="code" maxlength="60" required></label><label>Name<input name="name" maxlength="180" required></label><label>Validity value<input type="number" name="validity_value" min="1"></label><label>Validity unit<select name="validity_unit"><option value="">No expiry policy</option><option value="days">Days</option><option value="months">Months</option><option value="years">Years</option></select></label><label>Template key<input name="template_key" maxlength="100"></label><input type="hidden" name="active" value="1"><button class="btn btn-navy">Save type</button></form></details>
<details class="admin-panel"><summary>Issue certificate</summary><form method="post" action="/admin/certificates" class="form-grid"><?= $csrf->field() ?><label>Type<select name="certificate_type" required><?php foreach($types as$t):if(!$t['active'])continue;?><option value="<?= $e($t['public_id']) ?>"><?= $e($t['name']) ?></option><?php endforeach;?></select></label><label>Holder type<select name="holder_type"><option value="member">Member</option><option value="person">Person</option></select></label><label>Holder<select name="holder" required><optgroup label="Members"><?php foreach($members as$m):?><option value="<?= $e($m['public_id']) ?>"><?= $e($m['membership_number'].' · '.$m['holder_name']) ?></option><?php endforeach;?></optgroup><optgroup label="People"><?php foreach($people as$p):?><option value="<?= $e($p['public_id']) ?>"><?= $e($p['full_name']) ?></option><?php endforeach;?></optgroup></select></label><label>Programme<select name="programme"><option value="">None</option><?php foreach($programmes as$p):?><option value="<?= $e($p['public_id']) ?>"><?= $e($p['code'].' · '.$p['name']) ?></option><?php endforeach;?></select></label><label>Event<select name="event"><option value="">None</option><?php foreach($events as$event):?><option value="<?= $e($event['public_id']) ?>"><?= $e($event['title']) ?></option><?php endforeach;?></select></label><label>Issue date<input type="date" name="issue_date" required></label><label>Expiry override<input type="date" name="expiry_date"></label><button class="btn btn-navy">Issue certificate</button></form></details>
<div class="admin-list"><?php foreach($certificates as$c):?><article class="admin-panel"><strong><?= $e($c['certificate_number']) ?></strong><p><?= $e($c['certificate_type'].' · '.$c['holder_reference']) ?></p><span class="status-pill"><?= $e($c['status']) ?></span><?php if($c['status']!=='revoked'):?><form method="post" action="/admin/certificates/<?= rawurlencode($c['public_id']) ?>/revoke" class="form-grid"><?= $csrf->field() ?><label>Revocation reason<textarea name="reason" minlength="10" maxlength="500" required></textarea></label><button class="btn btn-outline-navy">Revoke</button></form><?php endif;?></article><?php endforeach;?></div></div></section>
